'use strict';
const $=id=>document.getElementById(id);
const definitions=[{id:'zz',title:'① 直接测 z',axis:'z',retained:1000,q:[1,0]}, {id:'zx',title:'② 改测 x',axis:'x',retained:1000,q:[.5,.5]}, {id:'zxz',title:'③ 保留 x+，再测 z',axis:'z',retained:500,q:[.5,.5]}];
const revealed=new Set();
const math=(tex,cls='')=>'<span class="'+cls+'" data-math="'+tex+'"></span>';
function instrument(x,id){return '<rect x="'+(x-5)+'" y="60" width="130" height="50" rx="3" fill="#9aa6b3"/><rect x="'+x+'" y="52" width="120" height="66" rx="5" fill="url(#metal-'+id+')" stroke="#8896a5" stroke-width="2"/><path d="M'+(x+6)+' 58h108" stroke="white" stroke-width="2"/>';}
function beam(x1,y1,x2,y2,id,gray=false,dash=false){return '<path d="M'+x1+' '+y1+'L'+x2+' '+y2+'" fill="none" stroke="'+(gray?'#8998a8':'#066bc4')+'" stroke-width="4" '+(dash?'stroke-dasharray="8 7" ':'')+'marker-end="url(#'+(gray?'gray':'blue')+'-'+id+')"/>';}
function geometry(d){const id=d.id,seq=id==='zxz';return '<svg viewBox="0 0 1232 '+(seq?190:150)+'" aria-hidden="true"><defs><linearGradient id="metal-'+id+'" x2="0" y2="1"><stop stop-color="#f8fafc"/><stop offset="1" stop-color="#c5ced8"/></linearGradient>'+['blue','gray'].map((c,i)=>'<marker id="'+c+'-'+id+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="'+(i?'#8998a8':'#066bc4')+'"/></marker>').join('')+'</defs>'+beam(144,85,250,85,id)+instrument(260,id)+(seq?beam(380,72,750,72,id)+beam(380,106,492,162,id,true)+'<rect x="494" y="143" width="18" height="39" rx="2" fill="#4d5968"/>'+instrument(760,id)+beam(880,72,1000,72,id)+beam(880,112,1000,128,id):beam(380,72,1000,72,id)+beam(380,112,1000,128,id,d.id==='zz'&&d.revealed,d.id==='zz'&&d.revealed))+'</svg>';}
function draw(){const reference=$('reference').value;const all=definitions.map(d=>{const visible=revealed.has(d.id),prob=reference==='initial'?d.q.map(p=>p*d.retained/1000):d.q;return {...d,revealed:visible,prob,counts:d.q.map(p=>p*d.retained)};});
$('experiments').innerHTML=all.map(d=>'<section class="experiment" data-id="'+d.id+'" data-revealed="'+d.revealed+'"><h2>'+d.title+'</h2><button data-reveal="'+d.id+'" aria-expanded="'+d.revealed+'">'+(d.revealed?'隐藏结果':'查看结果')+'</button>'+geometry(d)+math('|z+\\rangle','label input')+math('\\mathrm{SG}\\;'+(d.id==='zxz'?'x':d.axis),'label device-label')+(d.id==='zxz'?math('\\mathrm{SG}\\;z','label device-label second-device')+'<div class="label retained">保留 '+math('x+')+'：'+(d.revealed?'50% · 500个':'?')+'</div>'+math('|x+\\rangle','label current')+'<div class="label blocked">挡住 '+math('x-')+'：'+(d.revealed?'50% · 500个':'?')+'</div><div class="label fraction-note">'+(d.revealed?(reference==='initial'?'每路占初始样本四分之一':'每路占末台入射样本一半'):'末台两路各占多少？')+'</div>':'')+d.prob.map((p,i)=>'<div class="label outlet '+(i?'negative':'positive')+'">'+math(d.axis+(i?'-':'+'))+'<span class="value">'+(d.revealed?Math.round(p*100)+'%':'?')+'</span><span class="counts">'+(d.revealed?d.counts[i]+'个':'')+'</span></div>').join('')+'</section>').join('');
document.querySelectorAll('[data-math]').forEach(el=>katex.render(el.dataset.math,el,{throwOnError:true,strict:'error'}));
$('basis-note').textContent=reference==='initial'?'末端百分比以各行初始1000个粒子为分母。':(revealed.has('zxz')?'末端百分比的分母：前两行1000个；第三行保留的500个。':'末端百分比以各行进入最后一台分析器的粒子数为分母。');
$('reveal-all').textContent=revealed.size===3?'隐藏全部结果':'显示全部结果';
window.labState={reference,rows:all};}
$('experiments').addEventListener('click',e=>{const b=e.target.closest('[data-reveal]');if(!b)return;const id=b.dataset.reveal;revealed.has(id)?revealed.delete(id):revealed.add(id);draw();document.querySelector('[data-reveal="'+id+'"]').focus();});
$('reference').addEventListener('change',draw);
$('reveal-all').addEventListener('click',()=>{if(revealed.size===3)revealed.clear();else definitions.forEach(d=>revealed.add(d.id));draw();});
$('reset').addEventListener('click',()=>{revealed.clear();$('reference').value='initial';draw();});
function fit(){const scale=Math.min(innerWidth/1280,innerHeight/720);$('slide').style.transform='scale('+scale+')';$('slide').style.left=(innerWidth-1280*scale)/2+'px';$('slide').style.top=(innerHeight-720*scale)/2+'px';}
window.addEventListener('resize',fit);document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'退出全屏':'全屏';fit();});
let fallback=false;$('fullscreen').addEventListener('click',async()=>{if(fallback){window.open(location.href,'_blank','noopener');return;}try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{fallback=true;$('fullscreen').textContent='新窗口放大';}});
draw();fit();
